-- PHOENIX ERP V3 — FULL TEST BUSINESS RESET — R3 controlled execution contract
-- Transaction body is frozen to the production-verified R2 rollback bundle. Only the
-- execution gate and terminal COMMIT differ from R2.
\set ON_ERROR_STOP on
\if :{?PRODUCTION_RESET_AUTHORIZED}
\else
  \set PRODUCTION_RESET_AUTHORIZED false
\endif
\if :PRODUCTION_RESET_AUTHORIZED
\else
  \echo 'R3 requires -v PRODUCTION_RESET_AUTHORIZED=true'
  \quit 3
\endif
BEGIN ISOLATION LEVEL SERIALIZABLE;
SET LOCAL statement_timeout='30min';
SET LOCAL lock_timeout='5s';
SET LOCAL search_path=public,pg_catalog;
SELECT current_database(), current_setting('server_version');
DO $$ BEGIN IF current_database() <> 'phoenix_erp' THEN RAISE EXCEPTION 'wrong database'; END IF; IF current_setting('server_version') NOT LIKE '16.%' THEN RAISE EXCEPTION 'wrong postgres major'; END IF; IF (SELECT system_identifier FROM pg_control_system()) <> 7641898445435437089 THEN RAISE EXCEPTION 'wrong system identifier'; END IF; END $$;
CREATE TEMP TABLE r2_baseline(table_name text PRIMARY KEY, classification text NOT NULL, pre_rows bigint NOT NULL) ON COMMIT DROP;
