CREATE TEMP TABLE r2_deleted(table_name text PRIMARY KEY, deleted_rows bigint NOT NULL) ON COMMIT DROP;
SELECT table_name,classification,pre_rows FROM r2_baseline ORDER BY table_name;
DO $$ BEGIN IF (SELECT count(*) FROM public.chanjet_writeback_outbox WHERE state IN ('PENDING','QUEUED','RETRYING')) <> 0 THEN RAISE EXCEPTION 'pending Chanjet writeback'; END IF; IF (SELECT count(*) FROM public.chanjet_wms_writeback_outbox WHERE state IN ('PENDING','QUEUED','RETRYING')) <> 0 THEN RAISE EXCEPTION 'pending WMS writeback'; END IF; END $$;
DO $$ BEGIN IF (SELECT count(*) FROM public.chanjet_sync_jobs WHERE status='RUNNING' AND request_scope ? 'orchestrationRunId') <> 0 THEN RAISE EXCEPTION 'durable Chanjet job still RUNNING'; END IF; END $$;
DO $$ DECLARE n integer; BEGIN SELECT count(*) INTO n FROM pg_trigger WHERE NOT tgisinternal AND tgname IN ('trg_sal_order_lifecycle_events_append_only','trg_guard_posted_store_settlement','packing_event_immutable','preserve_pkg_packing_code_registry','preserve_pkg_packing_code_claims') AND tgenabled='O'; IF n <> 5 THEN RAISE EXCEPTION 'protected trigger precondition failed: %',n; END IF; END $$;
ALTER TABLE public.sal_order_lifecycle_events DISABLE TRIGGER trg_sal_order_lifecycle_events_append_only;
ALTER TABLE public.sal_store_settlements DISABLE TRIGGER trg_guard_posted_store_settlement;
ALTER TABLE public.pkg_packing_events DISABLE TRIGGER packing_event_immutable;
ALTER TABLE public.pkg_packing_code_registry DISABLE TRIGGER preserve_pkg_packing_code_registry;
ALTER TABLE public.pkg_packing_code_claims DISABLE TRIGGER preserve_pkg_packing_code_claims;
UPDATE public.sal_store_sale_tenders SET reversal_of_tender_id=NULL;
UPDATE public.pkg_packing_events SET session_id=NULL;
