DO $$ BEGIN IF EXISTS (SELECT 1 FROM public.fin_cash_accounts WHERE current_balance IS DISTINCT FROM opening_balance) THEN RAISE EXCEPTION 'cash derived balance mismatch'; END IF; IF EXISTS (SELECT 1 FROM public.store_inventory WHERE COALESCE(qty,0)<>0) THEN RAISE EXCEPTION 'store inventory not zero'; END IF; IF EXISTS (SELECT 1 FROM public.wms_stock_balance WHERE COALESCE(qty,0)<>0 OR COALESCE(locked_qty,0)<>0) THEN RAISE EXCEPTION 'wms stock balance not zero'; END IF; IF EXISTS (SELECT 1 FROM public.sal_customers WHERE COALESCE(credit_used,0)<>0 OR credit_status IS DISTINCT FROM 'NORMAL' OR last_overdue_at IS NOT NULL) THEN RAISE EXCEPTION 'customer credit derived state mismatch'; END IF; IF EXISTS (SELECT 1 FROM public.ord_customers WHERE COALESCE(credit_used,0)<>0) THEN RAISE EXCEPTION 'legacy customer credit derived state mismatch'; END IF; END $$;
SET CONSTRAINTS ALL IMMEDIATE;
SELECT 'R3_EXECUTION_PRECOMMIT_PASS' AS result, (SELECT COALESCE(sum(deleted_rows),0) FROM r2_deleted) AS deleted_rows;
COMMIT;
